parameters.jsCode:
const cfg = $('⚙️ CONFIG').first().json;
const wh  = $('Webhook').first().json.body || {};
const turn = $('Build Turn').first().json || {};
const out = $('AI Agent').first().json.output || {};

const maxBubbles = Number(cfg.max_bubbles ?? 3);
let msgs = Array.isArray(out.messages) ? out.messages
         : (out.messages ? [String(out.messages)] : []);
msgs = msgs.map(m => String(m ?? '').replace(/\s*[—]\s*|\s+[–-]\s+/g, ', ').trim().replace(/^(?:Absolut|Visst|Okej|Okey|Toppen|Självklart|Sure|Okay|Absolutely|Of course|Certainly|Alright|Sounds good|Selvä|Okei|Kiva kuulla)\s*[,!.]\s+(?=\S)/i, '').replace(/^\p{Ll}/u, (c) => c.toUpperCase())).filter(Boolean).slice(0, maxBubbles);

const ended    = out.end_conversation === true;
const handoff  = out.handoff === true;
let reaction = String(out.reaction ?? '').trim().slice(0, 4);
let reaction_source = reaction ? 'model' : 'none';

const rawUser = String(turn.raw_text || '').trim();
const lastLine = rawUser.split('\n').map(s => s.trim()).filter(Boolean).pop() || rawUser;
const isFrustrated = /\b(fuck you|kill|suicide|self harm)\b/i.test(lastLine);
// strip model reactions that are too eager on every turn — cadence handles sparse taps
const low = lastLine.toLowerCase().replace(/[^a-z0-9\s']/g,'').trim();
const softAck = /^(thanks|thank you|cheers|cool|nice|perfect|great|awesome)\b/.test(low);
const isLaugh = /😂|😅|lol|haha/i.test(lastLine);
if (reaction && !(softAck || isLaugh)) {
  // model reactions only for thanks/laugh; sparse cadence handles the rest
  reaction = '';
  reaction_source = 'none';
}
if (isFrustrated) { reaction = ''; reaction_source = 'none'; }

const minGap = Number(cfg.reaction_min_gap ?? 7);
const maxGap = Number(cfg.reaction_max_gap ?? 12);
let since = Number(turn.turns_since_reaction || 0);
let every = turn.reaction_every_n == null ? null : Number(turn.reaction_every_n);
if (!every || every < minGap || every > maxGap) {
  every = minGap + Math.floor(Math.random() * (maxGap - minGap + 1));
}
if (!reaction && !isFrustrated && (since + 1) >= every) {
  reaction = ['👍','😄','😅'][Math.floor(Math.random()*3)];
  reaction_source = 'cadence';
  since = -1;
}
const next_since = reaction ? 0 : (since + 1);
const next_every = reaction ? (minGap + Math.floor(Math.random() * (maxGap - minGap + 1))) : every;

let fu = Number(out.followup_seconds ?? 0);
if (!Number.isFinite(fu) || fu <= 0 || ended || handoff) fu = 0;
if (fu > 0) {
  fu = Math.max(fu, Number(cfg.min_followup_seconds ?? 45));
  fu = Math.min(fu, Number(cfg.max_followup_seconds ?? 900));
}

const perChar = Number(cfg.typing_ms_per_char ?? 18);
const dMin = Number(cfg.min_bubble_delay_seconds ?? 0.15);
const dMax = Number(cfg.max_bubble_delay_seconds ?? 0.9);

const base = {
  to_phone: wh.from_phone,
  staging: turn.staging === true,
  session_key: `${cfg.tenant_key}_${wh.from_phone}`,
  instance_id: cfg.wasup_instance_id,
  anchor_message_id: wh.message_id,
  reply_to_message_id: wh.whatsapp_message_id || wh.message_id,
  followup_seconds: fu, end_conversation: ended, handoff,
  next_turns_since_reaction: next_since,
  next_reaction_every_n: next_every,
  reaction_source
};

const wantsTime = /reconcil|täsm|tasma|stämmer inte|somewhere else|muualle|annanstan|somwehre/i.test(rawUser)
if (wantsTime && msgs.length && !msgs.join('\n').includes('?')) {
  const sample = (rawUser + '\n' + msgs.join('\n')).toLowerCase()
  const swedish = /\b(varför|jag|inte|stämmer|annanstan|besikt)\b/.test(sample)
  const finnish = /[äö]|miksi|mitä|lähden|muualle|etsitä/.test(sample)
  const ask = finnish && !swedish ? 'Etsitäänkö silti aika?' : swedish ? 'Ska jag hitta en tid?' : 'Want me to find you a time?'
  msgs[msgs.length - 1] = msgs[msgs.length - 1].replace(/[.!\s]+$/, '') + '. ' + ask
}
if (msgs.length === 0) {
  return [{ json: { ...base, seq: 0, total: 0, text: '', delay_seconds: 0, skip_send: true,
                    reaction, } }];
}

return msgs.map((text, i) => {
  let d = Math.round((text.length * perChar) / 1000 * 10) / 10;
  d = Math.min(Math.max(d, dMin), dMax);
  if (i === 0) d = 0; // first bubble immediately — Wasup typingSimulation covers feel
  return { json: {
    ...base,
    // CRITICAL: only first item carries reaction so we don't react N times
    reaction: i === 0 ? reaction : '',
    seq: i + 1, total: msgs.length, text,
    delay_seconds: d, skip_send: false
  } };
});

let bubble;
try { bubble = $('Loop Bubbles').first().json; } catch (e) { bubble = null; }
if (!bubble || bubble.text === undefined) bubble = $('Plan Delivery').first().json;
const db = $input.first().json || {};
const rem = Number(db.typing_remaining_seconds || 0);
const slice = Math.min(Math.max(rem, 0), Number(($('⚙️ CONFIG').first().json.typing_recheck_seconds) || 3));
const limit = Date.now() + 1000
let hold = null
while (Date.now() < limit) {
  try {
    if ($('Hold For Composing').isExecuted) {
      hold = $('Hold For Composing').first().json || {}
      break
    }
  } catch (error) {}
  await new Promise((resolve) => setTimeout(resolve, 100))
}
const reply = hold && typeof hold.reply === 'string' ? hold.reply.trim() : ''
const owned = Number(bubble.seq) === 1 && !!reply && reply === String(bubble.text || '').trim()
return [{ json: {
  ...bubble,
  skip_send: owned ? true : bubble.skip_send === true,
  webhook_owned: owned,
  user_replied: db.user_replied === true,
  user_typing: db.user_typing === true,
  typing_remaining_seconds: rem,
  typing_wait_seconds: slice > 0 ? slice : Number(($('⚙️ CONFIG').first().json.typing_recheck_seconds) || 3)
} }];

// Emits ONE item if a double-text is due, otherwise emits nothing at all —
// an empty return stops this branch dead. Reads Plan Delivery directly because
// the loop's "done" output carries send-API responses, not our payload.
const plan = $('Plan Delivery').first().json;
if (!plan.followup_seconds || plan.followup_seconds <= 0) return [];
return [{ json: {
  session_key: plan.session_key,
  anchor_message_id: plan.anchor_message_id,
  to_phone: plan.to_phone,
  instance_id: plan.instance_id,
  followup_seconds: plan.followup_seconds
} }];

const ctx = $('Follow-up Due?').first().json;
const db = $input.first().json || {};
const rem = Number(db.typing_remaining_seconds || 0);
return [{ json: { ...ctx, user_replied: db.user_replied === true, user_typing: db.user_typing === true,
  typing_remaining_seconds: rem,
  typing_wait_seconds: Math.min(Math.max(rem, 1), Number(($('⚙️ CONFIG').first().json.typing_recheck_seconds) || 3))
} }];

const ctx = $input.first().json;
const agent_input = [
  '[TURN]',
  'turn_type: your_own_followup',
  `local_time: ${new Date().toISOString()}`,
  `current_time: ${$now.setZone('Europe/Helsinki').toFormat('HH:mm')} (Europe/Helsinki)`,
  `seconds_since_your_last_message: ${ctx.followup_seconds}`,
  'note: the user has NOT replied. You decided this thread was worth chasing.',
  'note: ONE short bubble. Add something new — a nudge, an easier option, or a',
  '      graceful way out. Do not repeat what you already said.',
  'note: followup_seconds MUST be 0 on this turn.'
].join('\n');
return [{ json: { ...ctx, agent_input } }];

// Follow-ups are ALWAYS a single bubble. No loop, no recursion, no chasing a chase.
const cfg = $('⚙️ CONFIG').first().json;
const ctx = $('Follow-up Due?').first().json;
const out = $input.first().json.output || {};

let msgs = Array.isArray(out.messages) ? out.messages : (out.messages ? [String(out.messages)] : []);
const text = msgs.map(m => String(m ?? '').replace(/\s*[—]\s*|\s+[–-]\s+/g, ', ').trim().replace(/^(?:Absolut|Visst|Okej|Okey|Toppen|Självklart|Sure|Okay|Absolutely|Of course|Certainly|Alright|Sounds good|Selvä|Okei|Kiva kuulla)\s*[,!.]\s+(?=\S)/i, '').replace(/^\p{Ll}/u, (c) => c.toUpperCase())).filter(Boolean).join(' ').trim();
if (!text) return [];

const perChar = Number(cfg.typing_ms_per_char ?? 45);
let d = Math.round((text.length * perChar) / 1000);
d = Math.min(Math.max(d, Number(cfg.min_bubble_delay_seconds ?? 2)),
             Number(cfg.max_bubble_delay_seconds ?? 9));

return [{ json: { ...ctx, text, staging: $('Build Turn').isExecuted && $('Build Turn').first().json.staging === true, delay_seconds: d,
                  end_conversation: out.end_conversation === true } }];

const ctx = $('Plan Follow-up Delivery').first().json;
const db = $input.first().json || {};
const rem = Number(db.typing_remaining_seconds || 0);
return [{ json: { ...ctx, user_replied: db.user_replied === true, user_typing: db.user_typing === true,
  typing_remaining_seconds: rem,
  typing_wait_seconds: Math.min(Math.max(rem, 1), Number(($('⚙️ CONFIG').first().json.typing_recheck_seconds) || 3))
} }];

const raw = $input.item.json || {};
let q = {};
try {
  if (typeof raw.query === 'string' && raw.query.trim().startsWith('{')) q = JSON.parse(raw.query);
  else if (raw.query && typeof raw.query === 'object') q = raw.query;
} catch (e) {}
const all = Object.assign({}, q, raw);
const slotId = String(all.slot_id || all.slotId || '').trim();
if (!slotId) return JSON.stringify({ success: false, error: 'slot_id required' });
if (!/^K1-\d{8}-\d{4}$/.test(slotId)) {
  return JSON.stringify({ success: false, error: 'Unknown slot_id. Call get_slots and use an exact returned slot_id.' });
}
const data = $getWorkflowStaticData('global');
data.k1_holds = data.k1_holds || {};
