const URL_RE = /https?:\/\/[^\s<>)]+/gi
function decorate(item) {
  const text = String(item.text || '')
  if (item.staging !== true) return { ...item, cta_url: '', cta_label: '', cta_body: text }
  const urls = text.match(URL_RE) || []
